94	fn agreement(claim: &str, cp: &Checkpoint, g: &HashMap<&str, Vec<&str>>) -> (Agree, String) {
95	    let low = claim.to_lowercase();
96	
97	    // 1. Scope contradiction: claim asserts isolation, Graph says the blast radius escapes.
98	    let iso = ["isolated", "does not touch", "nothing else", "contained", "no other"];
99	    if iso.iter().any(|w| low.contains(w)) {
100	        let touched: HashSet<&str> = cp.files.iter().map(|s| s.as_str()).collect();
101	        let reach: Vec<&str> = touched.iter()
102	            .filter_map(|f| g.get(f))
103	            .flatten()
104	            .copied()
105	            .filter(|d| !touched.contains(d))
106	            .collect();
107	        if !reach.is_empty() {
108	            return (Agree::Contradicted,
109	                format!("claims isolation; Graph reach escapes to {}", reach.len()));
110	        }
111	    }
112	
113	    // 2. File contradiction: claim names a path the commit never touched.
114	    for t in terms(claim).iter().filter(|t| t.contains('/') || t.ends_with(".go")) {
115	        if !cp.files.iter().any(|f| f.to_lowercase().contains(t.as_str())) {
116	            return (Agree::Contradicted, format!("references {} which this commit did not touch", t));
117	        }
118	    }
119	
120	    // 3. Lexical agreement with what the commit says it did.
121	    // 3. Polarity flip: same topic, opposite action.
122	    let pc = polarity(claim);
123	    // Conventional-commit prefixes carry polarity the verb list misses:
124	    // "feat:"/"fix:" are additive, "revert:" is subtractive.
125	    let mut pm = polarity(&cp.commit_message);
126	    if pm == 0 {
127	        let m = cp.commit_message.to_lowercase();
128	        if m.starts_with("feat") || m.starts_with("fix") || m.starts_with("perf") { pm = 1; }
129	        else if m.starts_with("revert") { pm = -1; }
130	    }
131	    if pc != 0 && pm != 0 && pc != pm {
132	        let ct = terms(&cp.commit_message);
133	        if terms(claim).intersection(&ct).count() >= 1 {
134	            return (Agree::Contradicted, "action polarity opposes the commit".into());
135	        }
136	    }
137	
138	    // 4. Lexical agreement.
139	    let ct = terms(&cp.commit_message);
140	    let clt = terms(claim);
141	    let shared = clt.intersection(&ct).count();
142	    if shared >= 2 {
143	        return (Agree::Corroborated, format!("{} terms match commit subject", shared));
144	    }
145	
146	    // 5. Mutual recall — brain-as-judge for the paraphrase case.
147	    if let Some(mr) = brain_judge(claim, cp) {
148	        if mr > 0.5 {
149	            return (Agree::Corroborated, format!("mutual recall {:.2} via memory graph", mr));
150	        }
151	    }
152	    (Agree::Neutral, "no overlap with commit subject".into())
153	}
