284	/// A. DIFF-GROUNDED VOCABULARY — compare the claim against the identifiers the
285	/// code actually introduces, not the prose of the commit subject. Splits
286	/// camelCase / snake_case so `maxAttempts` yields {max, attempts}.
287	fn split_ident(w: &str) -> Vec<String> {
288	    let mut out = Vec::new();
289	    for part in w.split(|c: char| c == '_' || c == '.' || c == '/') {
290	        let mut cur = String::new();
291	        for ch in part.chars() {
292	            if ch.is_uppercase() && !cur.is_empty() { out.push(cur.to_lowercase()); cur.clear(); }
293	            if ch.is_alphanumeric() { cur.push(ch); }
294	        }
295	        if !cur.is_empty() { out.push(cur.to_lowercase()); }
296	    }
297	    out.into_iter().filter(|w| w.len() > 2).collect()
298	}
