317	    if hits.len() >= 2 {
318	        let mut names: Vec<&str> = hits.iter().map(|s| s.as_str()).collect();
319	        names.sort();
320	        Some((hits.len() as f32, format!("{} diff symbols: {}", hits.len(), names.join("/"))))
321	    } else { None }
