326	fn strat_spread(claim: &str, cp: &Checkpoint) -> Option<(f32, String)> {
327	    JUDGE.with(|j| j.borrow().as_ref().and_then(|b| {
328	        let res = b.activate_scoped(claim, None, None, 24);
329	        let want = format!("COMMIT {}:", cp.commit_sha);
330	        res.recalls.iter().enumerate()
331	            .find(|(_, r)| r.episode.content.starts_with(&want))
332	            .map(|(rank, r)| (r.activation / (1.0 + rank as f32 * 0.25),
333	                              format!("graph spread rank {} act {:.2}", rank, r.activation)))
334	            .filter(|(sc, _)| *sc > 0.35)
335	    }))
336	}
