410	fn score(name: &str, results: &[(Agree, Agree)]) {
411	    // Contradiction is the decision that matters: precision/recall on that class.
412	    let tp = results.iter().filter(|(p,t)| *p==Agree::Contradicted && *t==Agree::Contradicted).count() as f32;
413	    let fp = results.iter().filter(|(p,t)| *p==Agree::Contradicted && *t!=Agree::Contradicted).count() as f32;
414	    let fnn= results.iter().filter(|(p,t)| *p!=Agree::Contradicted && *t==Agree::Contradicted).count() as f32;
415	    let acc = results.iter().filter(|(p,t)| p==t).count() as f32 / results.len() as f32;
416	    let prec = if tp+fp>0.0 {tp/(tp+fp)} else {0.0};
417	    let rec  = if tp+fnn>0.0 {tp/(tp+fnn)} else {0.0};
418	    let f1   = if prec+rec>0.0 {2.0*prec*rec/(prec+rec)} else {0.0};
419	    println!("   {:<22} acc {:.2}   contradiction P {:.2} R {:.2} F1 {:.2}", name, acc, prec, rec, f1);
420	}
